SELECT 
  FROM tb_inquiries i
  LEFT JOIN tb_courses c ON c.id = i.course_id
  JOIN tb_users u ON u.id = i.user_id
 WHERE i.user_id = #{userId}

   AND i.status = #{status}

ORDER BY i.created_at DESC, i.id ASC
LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(*)
  FROM tb_inquiries i
 WHERE i.user_id = #{userId}

   AND i.status = #{status}

SELECT 
  FROM tb_inquiries i
  JOIN tb_courses c ON c.id = i.course_id
  JOIN tb_course_instructors ci ON ci.course_id = c.id
  JOIN tb_users u ON u.id = i.user_id
 WHERE ci.user_id = #{instructorUserId}

   AND i.status = #{status}


   AND i.course_id = #{courseId}

ORDER BY i.created_at DESC, i.id ASC
LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(*)
  FROM tb_inquiries i
  JOIN tb_course_instructors ci ON ci.course_id = i.course_id
 WHERE ci.user_id = #{instructorUserId}

   AND i.status = #{status}


   AND i.course_id = #{courseId}

SELECT 
  FROM tb_inquiries i
  JOIN tb_courses c ON c.id = i.course_id
  JOIN tb_users u ON u.id = i.user_id
 WHERE c.institution_id = #{institutionId}

   AND i.status = #{status}


   AND i.course_id = #{courseId}

ORDER BY i.created_at DESC, i.id ASC
LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(*)
  FROM tb_inquiries i
  JOIN tb_courses c ON c.id = i.course_id
 WHERE c.institution_id = #{institutionId}

   AND i.status = #{status}


   AND i.course_id = #{courseId}
